# Surah Yusuf (chapter 12) — part 7: ayat 61-70 (IDs 1657-1666)
SURAH = 12

ENTRIES = {
1657: (
"انہوں نے — کہا — ہم — عنقریب — ان — سے — اس — کے لیے — اپنے باپ — سے اجازت — لیں گے — اور — ہم — یقیناً — کرنے والے — ہیں",
"""۱۔ بھائی — بینیامین — کو مصر لے جانے کا وعدہ — کرتے ہیں۔
۲۔ ’’قَالُوا سَنُرَاوِدُ عَنْهُ أَبَاهُ وَإِنَّا لَفَاعِلُونَ‘‘ — انہوں نے — کہا — ہم — عنقریب — ان — سے — اس — کے لیے — اپنے باپ — سے اجازت — لیں گے — اور — ہم — یقیناً — کرنے والے — ہیں — یعنی انہوں نے — کہا — ہم — عنقریب — اس — کے لیے — اپنے — باپ — سے — اجازت — لیں گے — اور — ہم — یقیناً — کرنے والے — ہیں۔
۳۔ عملی سبق: وعدہ — پورا — کرو؛ لیکن اللہ — ہی — کامیابی — دیتا ہے۔"""
),
1658: (
"اور — یوسفؑ — نے — اپنے جوانوں — سے — کہا — ان — کی — تجارت کی پونجی — ان — کے گدھوں — میں — رکھ دو — شاید — ان — کو — اس — کا — اپنے اہل — کے پاس لوٹنے پر — پتہ — چلے — شاید — وہ — واپس — آ جائیں",
"""۱۔ یوسفؑ — گِراھکوں کی پونجی — واپس — رکھواتے ہیں؛ اچھے سلوک — میں — عزت — ہے۔
۲۔ ’’وَقَالَ لِفِتْيَانِهِ اجْعَلُوا بِضَاعَتَهُمْ فِي رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَهَا إِذَا انقَلَبُوا إِلَىٰ أَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ‘‘ — اور — یوسفؑ — نے — اپنے جوانوں — سے — کہا — ان — کی — تجارت کی پونجی — ان — کے گدھوں — میں — رکھ دو — شاید — ان — کو — اس — کا — اپنے اہل — کے پاس لوٹنے پر — پتہ — چلے — شاید — وہ — واپس — آ جائیں — یعنی یوسفؑ — نے — اپنے جوانوں — سے کہا — ان — کی — پونجی — ان — کے گدھوں — میں — رکھ دو — شاید — وہ — اس کا — اپنے گھر — پہنچنے پر — پتہ — چلائیں — شاید — وہ واپس — آ جائیں۔
۳۔ عملی سبق: اچھے سلوک — واپسی — کا — سبب — بنتے ہیں۔"""
),
1659: (
"پس — جب — وہ — اپنے باپ — کے پاس — لوٹے — انہوں نے — کہا — اے — ہمارے ابا — ہمیں — پیمانہ — نہیں دیا گیا — پس — ہمارے بھائی — کو — ہمارے ساتھ — بھیجیں — کہ ہم — غلہ — لے آئیں — اور — ہم — اس — کے — محافظ — ہیں",
"""۱۔ بھائی — واپس آکر باپ — سے بینیامین — کو — ساتھ — لے جانے کی اجازت — مانگتے ہیں۔
۲۔ ’’فَلَمَّا رَجَعُوا إِلَىٰ أَبِيهِمْ قَالُوا يَا أَبَانَا مُنِعَ مِنَّا الْكَيْلُ فَأَرْسِلْ مَعَنَا أَخَانَا نَكْتَلْ وَإِنَّا لَهُ لَحَافِظُونَ‘‘ — پس — جب — وہ — اپنے باپ — کے پاس — لوٹے — انہوں نے — کہا — اے — ہمارے ابا — ہمیں — پیمانہ — نہیں دیا گیا — پس — ہمارے بھائی — کو — ہمارے ساتھ — بھیجیں — کہ ہم — غلہ — لے آئیں — اور — ہم — اس — کے — محافظ — ہیں — یعنی پس — جب — وہ — اپنے باپ — کے پاس — لوٹے — انہوں نے کہا — اے — ہمارے ابا — ہمیں — پیمانہ — نہیں — دیا — گیا — پس — ہمارے — بھائی — کو — ہمارے ساتھ — بھیجیں — کہ ہم — غلہ — لے آئیں — اور — ہم — اس — کے — محافظ — ہیں۔
۳۔ عملی سبق: ضرورت — جھوٹ — سے زیادہ — حکمت — مانگتی ہے۔"""
),
1660: (
"انہوں نے کہا — کیا — میں — تم — ا — اس پر — بھروسہ — کر سکتا ہوں — مگر — ویسا ہی — جیسا — میں — نے — اس — سے پہلے — اس — کے بھائی — پر — بھروسہ کیا تھا — پس — اللہ — بہتر — حفاظت کرنے والا — ہے — اور — وہ — سب — سے زیادہ — رحم کرنے والا — ہے",
"""۱۔ یعقوبؑ — اپنے پچھلے تجربے کی بنیاد پر — شک — کرتے ہیں؛ اللہ — پر — بھروسہ — کرتے ہیں۔
۲۔ ’’قَالَ هَلْ آمَنُكُمْ عَلَيْهِ إِلَّا كَمَا أَمِنتُكُمْ عَلَىٰ أَخِيهِ مِن قَبْلُ فَاللَّهُ خَيْرٌ حَافِظًا وَهُوَ أَرْحَمُ الرَّاحِمِينَ‘‘ — انہوں نے کہا — کیا — میں — تم — ا — اس پر — بھروسہ — کر سکتا ہوں — مگر — ویسا ہی — جیسا — میں — نے — اس — سے پہلے — اس — کے بھائی — پر — بھروسہ کیا تھا — پس — اللہ — بہتر — حفاظت کرنے والا — ہے — اور — وہ — سب — سے زیادہ — رحم کرنے والا — ہے — یعنی یعقوبؑ نے — کہا — کیا — میں — تمہیں — اس — پر — ویسا ہی — بھروسہ — کر سکتا ہوں — جیسا — میں — نے پہلے — اس کے بھائی — پر — بھروسہ کیا تھا — پس — اللہ — بہتر — حفاظت کرنے والا — ہے — اور — وہ سب — سے زیادہ — رحم کرنے والا — ہے۔
۳۔ عملی سبق: اللہ کی حفاظت — سب — سے بہتر — ہے۔"""
),
1661: (
"اور — جب — انہوں نے — اپنا — سامان کھولا — انہوں نے — اپنی پونجی — انہیں — واپس دی گئی — پائی — انہوں نے کہا — اے — ہمارے ابا — ہم — کیا چاہتے ہیں — یہ — ہماری — پونجی — ہمیں — واپس — دے دی گئی — اور — ہم — اپنے اہل — کے لیے غلہ — لائیں گے — اور — ہم — اپنے بھائی — کی حفاظت — کریں گے — اور — ایک اونٹ — کا — غلہ — زیادہ — لیں گے — یہ — ایک — آسان — پیمانہ — ہے",
"""۱۔ واپس — لوٹنے پر — پونجی — لوٹی ہوئی — پائی؛ بینیامین — کو — لے — جانے کا مطالبہ — مضبوط — ہوا۔
۲۔ ’’وَلَمَّا فَتَحُوا مَتَاعَهُمْ وَجَدُوا بِضَاعَتَهُمْ رُدَّتْ إِلَيْهِمْ قَالُوا يَا أَبَانَا مَا نَبْغِي هَٰذِهِ بِضَاعَتُنَا رُدَّتْ إِلَيْنَا وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍ ذَٰلِكَ كَيْلٌ يَسِيرٌ‘‘ — اور — جب — انہوں نے — اپنا — سامان کھولا — انہوں نے — اپنی پونجی — انہیں — واپس دی گئی — پائی — انہوں نے کہا — اے — ہمارے ابا — ہم — کیا چاہتے ہیں — یہ — ہماری — پونجی — ہمیں — واپس — دے دی گئی — اور — ہم — اپنے اہل — کے لیے غلہ — لائیں گے — اور — ہم — اپنے بھائی — کی حفاظت — کریں گے — اور — ایک اونٹ — کا — غلہ — زیادہ — لیں گے — یہ — ایک — آسان — پیمانہ — ہے — یعنی جب — انہوں نے — اپنا — سامان — کھولا — انہوں نے اپنی پونجی — واپس — ہوئی — پائی — انہوں نے کہا — اے ہمارے — ابا — ہم — کیا چاہتے — ہیں — یہ ہماری پونجی — ہمیں — واپس — دے دی — گئی — اور — ہم — اپنے — اہل کے لیے — غلہ — لائیں گے — اور — ہم — اپنے بھائی — کی حفاظت — کریں گے — اور — ایک — اونٹ — کا غلہ — زیادہ — لیں گے — یہ — ایک — آسان — پیمانہ — ہے۔
۳۔ عملی سبق: اچھے تعلقات — کاروباری — بھی — شعور — دلاتے ہیں۔"""
),
1662: (
"انہوں نے کہا — میں — اسے — ہر گز — تمہارے ساتھ نہیں — بھیجوں گا — جب تک — تم — اللہ کی قسم — لے کر — عہد — نہ دو — کہ — ضرور — اس — کو میرے پاس — واپس — لاؤ گے — سوائے — اس — صورت کے — کہ — تم — گھیر — لیے — جاؤ — پس — جب — انہوں نے — اس — کو — عہد دیا — تو — انہوں نے کہا — اللہ — اس پر — نگہبان — ہے — جو ہم کہتے ہیں",
"""۱۔ یعقوبؑ — اللہ — کی قسم کا عہد — لے کر — بینیامین — بھیجنے پر تیار — ہوئے۔
۲۔ ’’قَالَ لَنْ أُرْسِلَهُ مَعَكُمْ حَتَّىٰ تُؤْتُونِ مَوْثِقًا مِّنَ اللَّهِ لَتَأْتُنَّنِي بِهِ إِلَّا أَن يُّحَاطَ بِكُمْ فَلَمَّا آتَوْهُ مَوْثِقَهُمْ قَالَ اللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ‘‘ — انہوں نے کہا — میں — اسے — ہر گز — تمہارے ساتھ نہیں — بھیجوں گا — جب تک — تم — اللہ کی قسم — لے کر — عہد — نہ دو — کہ — ضرور — اس — کو میرے پاس — واپس — لاؤ گے — سوائے — اس — صورت کے — کہ — تم — گھیر — لیے — جاؤ — پس — جب — انہوں نے — اس — کو — عہد دیا — تو — انہوں نے کہا — اللہ — اس پر — نگہبان — ہے — جو ہم کہتے ہیں — یعنی یعقوبؑ نے — کہا — میں — اسے — تمہارے — ساتھ — ہرگز — نہیں — بھیجوں گا — جب تک — تم — اللہ — کی — قسم — کے — ساتھ — عہد — دو — کہ — ضرور — اسے — میرے — پاس — واپس — لاؤ گے — سوائے — اس — صورت — کے — کہ تم — گھیر — لیے — جاؤ؛ پس — جب — انہوں نے — اس — کو — عہد — دیا — تو — یعقوبؑ نے — کہا — اللہ — اس — بات — پر — نگہبان ہے — جو ہم کہتے ہیں۔
۳۔ عملی سبق: عہد — کو پورا — کرنا — ایمان کا تقاضا — ہے۔"""
),
1663: (
"اور — انہوں نے کہا — اے میرے بیٹو — ایک ہی دروازے — سے داخل نہ ہو — بلکہ — مختلف دروازوں — سے داخل ہو — اور — میں — اللہ — کی طرف سے تمہارے لیے — کچھ — فائدے — کی بات — نہیں — کرتا — فیصلہ — صرف اللہ کا ہے — اسی پر — میں نے بھروسہ — کیا — اور — اسی پر — بھروسہ کرنے والوں — کو — بھروسہ کرنا چاہیے",
"""۱۔ یعقوبؑ — بچوں — کو — ایک دروازے — سے داخل ہونے سے منع — حسد — سے بچاؤ — کی تدبیر۔
۲۔ ’’وَقَالَ يَا بَنِيَّ لَا تَدْخُلُوا مِن بَابٍ وَاحِدٍ وَادْخُلُوا مِنْ أَبْوَابٍ مُّتَفَرِّقَۃٍ وَمَا أُغْنِي عَنكُم مِّنَ اللَّهِ مِن شَيْءٍ إِنِ الْحُكْمُ إِلَّا لِلَّهِ عَلَيْهِ تَوَكَّلْتُ وَعَلَيْهِ فَلْيَتَوَكَّلِ الْمُتَوَكِّلُونَ‘‘ — اور — انہوں نے کہا — اے میرے بیٹو — ایک ہی دروازے — سے داخل نہ ہو — بلکہ — مختلف دروازوں — سے داخل ہو — اور — میں — اللہ — کی طرف سے تمہارے لیے — کچھ — فائدے — کی بات — نہیں — کرتا — فیصلہ — صرف اللہ کا ہے — اسی پر — میں نے بھروسہ — کیا — اور — اسی پر — بھروسہ کرنے والوں — کو — بھروسہ کرنا چاہیے — یعنی یعقوبؑ نے کہا — اے — میرے — بیٹو — ایک ہی — دروازے — سے داخل — نہ ہو — بلکہ — مختلف — دروازوں — سے — داخل ہو — اور — میں — تمہارے لیے — اللہ — کی طرف سے — کچھ — کچھ — نفع — نہیں — دے — سکتا — فیصلہ — صرف — اللہ — کا — ہے؛ اسی — پر — میں — نے — بھروسہ — کیا — اور — اسی — پر — بھروسہ — کرنے والوں کو — بھروسہ — کرنا — چاہیے۔
۳۔ عملی سبق: تدبیر — بھی — ایمان — کا حصہ — ہے؛ مگر — فیصلہ — اللہ — کا — ہے۔"""
),
1664: (
"اور — جب — وہ — اس — طرح داخل ہوئے — جیسے ان کے باپ — نے حکم دیا تھا — وہ — اللہ کی طرف سے — ان کے لیے — کچھ نہیں دفع کر سکتا تھا — مگر — یعقوب — کے دل — کی ایک خواہش — تھی — اس کو — اس نے پورا — کیا — اور — بے شک — وہ — اس — چیز میں — والا — علم رکھتا تھا جس — کے ہم نے اسے — سکھایا — لیکن — اکثر لوگ — نہیں — جانتے",
"""۱۔ یعقوبؑ کی تدبیر — کام — کرتی ہے؛ اللہ کا فیصلہ — رد نہیں ہوتا۔
۲۔ ’’وَلَمَّا دَخَلُوا مِنْ حَيْثُ أَمَرَهُمْ أَبُوهُم مَّا كَانَ يُغْنِي عَنْهُم مِّنَ اللَّهِ مِن شَيْءٍ إِلَّا حَاجَۃً فِي نَفْسِ يَعْقُوبَ قَضَاهَا وَإِنَّهُ لَذُو عِلْمٍ لِّمَا عَلَّمْنَاهُ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ‘‘ — اور — جب — وہ — اس — طرح داخل ہوئے — جیسے ان کے باپ — نے حکم دیا تھا — وہ — اللہ کی طرف سے — ان کے لیے — کچھ نہیں دفع کر سکتا تھا — مگر — یعقوب — کے دل — کی ایک خواہش — تھی — اس کو — اس نے پورا — کیا — اور — بے شک — وہ — اس — چیز میں — والا — علم رکھتا تھا جس — کے ہم نے اسے — سکھایا — لیکن — اکثر لوگ — نہیں — جانتے — یعنی جب وہ — اسی طرح — داخل — ہوئے — جیسے ان کے باپ — نے — حکم دیا تھا — وہ اللہ — کی طرف سے — ان — کے — لیے — کچھ — کچھ — نفع نہ دے سکتے تھے — مگر — یعقوبؑ کے دل — کی ایک — خواہش تھی — اس کو اس — نے پورا کیا — اور — بے شک — وہ — اس چیز — میں — والا علم — رکھتا تھا — جس — کے — ہم — نے — اسے — سکھایا — لیکن اکثر — لوگ — نہیں — جانتے۔
۳۔ عملی سبق: تدبیر — اللہ — کا — فیصلہ — نہیں — بدلتی؛ مگر — تدبیر — مشروع — ہے۔"""
),
1665: (
"اور — جب — وہ — یوسفؑ — کے پاس داخل ہوئے — اس — نے — اپنے — بھائی — کو — اپنی طرف — بلوا — لیا — اس — نے کہا — بے شک — میں — تمہارا — بھائی ہوں — پس — غمگین — نہ — ہو — جو — وہ — کرتے تھے",
"""۱۔ یوسفؑ — اپنے بھائی — کو دھوکا نہیں دیتے؛ خود — کو ظاہر کرتے ہیں۔
۲۔ ’’وَلَمَّا دَخَلُوا عَلَىٰ يُوسُفَ آوَىٰ إِلَيْهِ أَخَاهُ قَالَ إِنِّي أَنَا أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا يَعْمَلُونَ‘‘ — اور — جب — وہ — یوسفؑ — کے پاس داخل ہوئے — اس — نے — اپنے — بھائی — کو — اپنی طرف — بلوا — لیا — اس — نے کہا — بے شک — میں — تمہارا — بھائی ہوں — پس — غمگین — نہ — ہو — جو — وہ — کرتے تھے — یعنی جب — وہ — یوسفؑ — کے پاس — داخل — ہوئے — اس — نے — اپنے — بھائی — کو — اپنی — طرف — بلوا — لیا — اس — نے — کہا — بے شک — میں — تمہارا — بھائی — ہوں — پس غمگین — نہ ہو — ان — کے — کرتوت سے۔
۳۔ عملی سبق: بھائی چارہ — رہنمائی — ہے — برداشت — کی حد — تک ہے۔"""
),
1666: (
"پس — جب — اس — نے — ان — کو — ان کے سامان سے — لیس کر دیا — اس — نے — پیالہ — اپنے — بھائی کے سفری سامان — میں — رکھ دیا — پھر — ایک — اعلان کرنے والا — نے — اعلان کیا — اے کارواں — بے شک — تم — چرانے والے — ہو",
"""۱۔ پیالہ — بینیامین کے — سامان — میں — رکھا گیا؛ اعلان ہوا — کاروان چور ہیں۔
۲۔ ’’فَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ جَعَلَ السِّقَايَۃَ فِي رَحْلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا الْعِيرُ إِنَّكُمْ لَسَارِقُونَ‘‘ — پس — جب — اس — نے — ان — کو — ان کے سامان سے — لیس کر دیا — اس — نے — پیالہ — اپنے — بھائی کے سفری سامان — میں — رکھ دیا — پھر — ایک — اعلان کرنے والا — نے — اعلان کیا — اے کارواں — بے شک — تم — چرانے والے — ہو — یعنی پس — جب — اس نے — ان — کو — ان — کے — سامان — سے لیس کر دیا — اس — نے پیالہ — اپنے — بھائی — کے سفری — سامان — میں رکھ — دیا — پھر — ایک — اعلان — کرنے والے — نے — اعلان کیا — اے کارواں — بے شک — تم — چور — ہو۔
۳۔ عملی سبق: حکمت — کی منصوبہ بندی — مسلسل — چلتی ہے۔"""
),
}
